1	<!DOCTYPE html>
2	<html lang="en">
3	<head>
4	  <meta charset="UTF-8">
5	  <meta name="viewport" content="width=device-width, initial-scale=1.0">
6	  <meta name="color-scheme" content="light dark">
7	  <title>Animated Circle - Interactive Demo</title>
8	  <meta name="description" content="A responsive, accessible circle that changes color when clicked">
9	  <style>
10	    *,
11	    *::before,
12	    *::after {
13	      box-sizing: border-box;
14	      margin: 0;
15	      padding: 0;
16	    }
17	    :root {
18	      color-scheme: light dark;
19	      --bg: #fff;
20	      --text: #374151;
21	      --fg: #2563eb;
22	      --shadow: rgba(0, 0, 0, 0.1);
23	    }
24	    [data-color="red"] { --fg: #dc2626; }
25	    [data-color="green"] { --fg: #16a34a; }
26	    [data-color="amber"] { --fg: #d97706; }
27	    [data-color="violet"] { --fg: #7c3aed; }
28	    [data-color="cyan"] { --fg: #0891b2; }
29	    @media (prefers-color-scheme: dark) {
30	      :root {
31	        --bg: #111;
32	        --text: #d1d5db;
33	        --fg: #93c5fd;
34	        --shadow: rgba(0, 0, 0, 0.6);
35	      }
36	      [data-color="red"] { --fg: #fca5a5; }
37	      [data-color="green"] { --fg: #86efac; }
38	      [data-color="amber"] { --fg: #fcd34d; }
39	      [data-color="violet"] { --fg: #c4b5fd; }
40	      [data-color="cyan"] { --fg: #67e8f9; }
41	    }
42	    @media (prefers-contrast: more) {
43	      :root {
44	        --shadow: rgba(0, 0, 0, 0.9);
45	      }
46	    }
47	    @media (forced-colors: active) {
48	      svg circle {
49	        stroke: CanvasText;
50	        stroke-width: 2;
51	      }
52	    }
53	    body {
54	      min-height: 100dvh;
55	      display: grid;
56	      place-items: center;
57	      padding: 1rem;
58	      background: var(--bg);
59	      color: var(--text);
60	      font-family: system-ui, -apple-system, sans-serif;
61	    }
62	    main {
63	      width: 100%;
64	      display: flex;
65	      flex-direction: column;
66	      align-items: center;
67	      text-align: center;
68	    }
69	    button {
70	      display: block;
71	      width: min(360px, 100%);
72	      aspect-ratio: 1;
73	      border: 0;
74	      border-radius: 50%;
75	      background: none;
76	      color: var(--fg);
77	      cursor: pointer;
78	      touch-action: manipulation;
79	      -webkit-tap-highlight-color: transparent;
80	      transition: color 0.4s ease;
81	    }
82	    button:focus-visible {
83	      outline: 3px solid var(--fg);
84	      outline-offset: 8px;
85	    }
86	    svg {
87	      display: block;
88	      width: 100%;
89	      height: 100%;
90	      overflow: visible;
91	      opacity: 0.9;
92	      filter: drop-shadow(0 8px 16px var(--shadow));
93	      transition: opacity 0.3s ease;
94	    }
95	    button:active svg,
96	    button:focus-visible svg {
97	      opacity: 1;
98	    }
99	    @media (hover: hover) {
100	      button:hover svg {
101	        opacity: 1;
102	      }
103	    }
104	    @media (prefers-reduced-motion: no-preference) {
105	      svg {
106	        transition:
107	          transform 0.3s cubic-bezier(0.34, 1.56, 0.64, 1),
108	          opacity 0.3s ease;
109	      }
110	      button:focus-visible svg {
111	        transform: scale(1.05);
112	      }
113	      button:active svg {
114	        transform: scale(0.97);
115	      }
116	    }
117	    @media (hover: hover) and (prefers-reduced-motion: no-preference) {
118	      button:hover:not(:active) svg {
119	        transform: scale(1.05);
120	      }
121	    }
122	    .status {
123	      margin-top: 2rem;
124	      font-weight: 600;
125	    }
126	    .hint {
127	      margin-top: 0.25rem;
128	      font-size: 0.875rem;
129	    }
130	  </style>
131	</head>
132	<body>
133	  <main>
134	    <button type="button" aria-label="Change circle color" aria-describedby="status hint">
135	      <svg viewBox="0 0 100 100" aria-hidden="true" focusable="false" xmlns="http://www.w3.org/2000/svg">
136	        <circle cx="50" cy="50" r="50" fill="currentColor"/>
137	      </svg>
138	    </button>
139	    <p class="status" id="status" role="status">Blue</p>
140	    <p class="hint" id="hint">Click, tap, or press Enter or Space to change the color</p>
141	  </main>
142	  <script>
143	    const button = document.querySelector('button');
144	    const status = document.querySelector('.status');
145	    const colors = ['blue', 'red', 'green', 'amber', 'violet', 'cyan'];
146	    const storageKey = 'circle-color';
147	
148	    const savedColor = localStorage.getItem(storageKey);
149	    let index = Math.max(colors.indexOf(savedColor), 0);
150	
151	    function applyColor() {
152	      const color = colors[index];
153	      if (color === 'blue') {
154	        delete button.dataset.color;
155	      } else {
156	        button.dataset.color = color;
157	      }
158	      status.textContent = color[0].toUpperCase() + color.slice(1);
159	      localStorage.setItem(storageKey, color);
160	    }
161	
162	    applyColor();
163	
164	    button.addEventListener('click', () => {
165	      index = (index + 1) % colors.length;
166	      applyColor();
167	    });
168	  </script>
169	</body>
170	</html>
